import{_ as a,a as i,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Go 包与模块：导入、导出与依赖方向","description":"由一个两包程序理解模块路径、可见性、依赖图、go.mod 与 go.sum 的职责。","frontmatter":{"title":"Go 包与模块：导入、导出与依赖方向","description":"由一个两包程序理解模块路径、可见性、依赖图、go.mod 与 go.sum 的职责。","showdocs":{"topics":[{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Go 实践课程","summary":"由一个两包程序理解模块路径、可见性、依赖图、go.mod 与 go.sum 的职责。","status":"active","related":[{"title":"Beego 工程维护：模块、MVC 与排错","link":"/programming/go/plus/ecosystem/base-beego","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 编码规范：格式、命名、接口与评审","link":"/programming/go/plus/practice/coding_guidelines","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 定时任务：Timer、Ticker、cron 与退出","link":"/programming/go/plus/practice/scheduling","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 高级并发实践：有界执行、背压、失败取消与保序","link":"/programming/go/plus/practice/concurrency","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 工具链：环境、构建、测试与命令速查","link":"/programming/go/toolchain","kind":"排错","scope":"general","audience":"general"}],"prev":{"text":"Go 泛型：类型参数、约束与推断","link":"/programming/go/base/intermediate/generics"},"next":{"text":"Go 第一条测试：用可观测结果验证行为","link":"/programming/go/base/intermediate/first-test"}},"hashRedirects":{"test":"/programming/go/base/intermediate/first-test#test","goroutine":"/programming/go/base/intermediate/concurrency#goroutine","race":"/programming/go/base/intermediate/concurrency#race","cancel":"/programming/go/base/intermediate/cancellation#cancel"},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Go 泛型：类型参数、约束与推断","link":"/programming/go/base/intermediate/generics"},"next":{"text":"Go 第一条测试：用可观测结果验证行为","link":"/programming/go/base/intermediate/first-test"}},"headers":[],"relativePath":"programming/go/base/intermediate/engineering.md","filePath":"programming/go/base/intermediate/engineering.md"}'),t={name:"programming/go/base/intermediate/engineering.md"};function o(r,e,p,l,d,c){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="go-包与模块-导入、导出与依赖方向" tabindex="-1">Go 包与模块：导入、导出与依赖方向 <a class="header-anchor" href="#go-包与模块-导入、导出与依赖方向" aria-label="Permalink to &quot;Go 包与模块：导入、导出与依赖方向&quot;">​</a></h1><p><span id="go-包、测试、调试与并发取消"></span></p><p>前置是<a href="/programming/go/base/basic/start#module">第一个可执行程序</a>和<a href="/programming/go/base/intermediate/functions#function">函数签名</a>。当一个小程序既要从终端使用，又要让测试直接调用里面的计算，可以把计算提取到独立的包。</p><h2 id="package" tabindex="-1">包、模块与工作目录 <a class="header-anchor" href="#package" aria-label="Permalink to &quot;包、模块与工作目录 {#package}&quot;">​</a></h2><p>包由同一目录中参与当前构建的一组源文件组成。包内普通源文件声明相同的包名，目录还可包含使用外部测试包名的 <code>_test.go</code>。包名决定代码中怎样引用它；导入路径在模块内通常由 <code>go.mod</code> 中的模块路径加目录的相对路径构成。两台电脑把项目摆在不同目录，同一个导入路径仍应有效。</p><p>模块是统一记录依赖与语言版本的单位，能够包含多个包。在空目录执行 <code>go mod init example.com/study</code>，创建 <code>mathutil</code> 子目录，再保存下列两个文件。它们属于同一个模块，各自只有一个包声明。</p><p><code>mathutil/add.go</code></p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">package</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mathutil</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b }</span></span></code></pre></div><p><code>main.go</code></p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">package</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fmt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">example.com/study/mathutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { fmt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mathutil.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) }</span></span></code></pre></div><p>在模块根目录执行 <code>go run .</code>，预期输出</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3</span></span></code></pre></div><p><code>Add</code> 的首字符是 Unicode 大写字母，可被其他包引用。把它改成 <code>add</code> 之后，工具仍能找到包，但 <code>main</code> 无法访问该成员。若把导入路径写错，失败发生在解析包时，这两类问题应分开检查。</p><p><code>go.mod</code> 保存模块身份、语言版本和所需依赖等约束。<code>go.sum</code> 保存下载过的相关模块内容和模块声明的校验摘要。示例只用标准库和同模块包，可能根本没有 <code>go.sum</code>。<code>go mod tidy</code> 会按导入关系增加缺失项、移除不再需要的项，文件已符合要求时也可能没有差异。外部模块如何选版本，见<a href="/programming/go/modules">模块依赖工作流</a>。</p><h2 id="construction" tabindex="-1">包之间的依赖方向 <a class="header-anchor" href="#construction" aria-label="Permalink to &quot;包之间的依赖方向 {#construction}&quot;">​</a></h2><p>每条 <code>import</code> 都让编译器在处理当前包前先处理被导入包。相互导入会形成循环，工具无法按依赖顺序构建它们。本例依赖关系是 <code>main → mathutil</code>。若计算函数为了打印结果又导入入口包，就把原本独立的计算绑到了一个特定程序。让计算返回值，由入口打印，可同时支持终端与测试。</p><p>当函数需要文件、存储等依赖时，可以通过普通参数或构造函数传入。构造函数在返回可用对象前验证必需依赖，资源的创建者与使用者约定关闭责任。对下游包只要求一个行为时，把小接口定义在调用方可以降低它对具体实现的依赖。导入路径能告诉你谁在编译期依赖谁，构造函数参数则说明运行时由谁提供对象。<a href="/programming/go/plus/practice/coding_guidelines#injection">通过 io.Writer 约定依赖与资源所有权</a></p><h2 id="exercise" tabindex="-1">练习与自检 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习与自检 {#exercise}&quot;">​</a></h2><p>将 <code>mathutil</code> 目录改名为 <code>arith</code>，保留 <code>package mathutil</code>。需要更新调用处的哪一部分？然后把可导出符号 <code>Add</code> 改为 <code>add</code>，再判断失败发生在哪一步。</p><details class="details custom-block"><summary>参考解法</summary><p>导入路径改为 <code>&quot;example.com/study/arith&quot;</code>，通过该路径找到的包仍声明为 <code>mathutil</code>，调用依旧写 <code>mathutil.Add</code>。函数名改为小写后即使找对目录，包外仍不能访问它。实际项目常让包名和目录末段一致，便于从调用追到源文件。</p></details><h2 id="测试与并发课程" tabindex="-1">测试与并发课程 <a class="header-anchor" href="#测试与并发课程" aria-label="Permalink to &quot;测试与并发课程&quot;">​</a></h2><p><span id="test"></span></p><p><a href="/programming/go/base/intermediate/first-test#test">第一条表驱动测试</a></p><p><span id="goroutine"></span><span id="race"></span><span id="cancel"></span></p><p><a href="/programming/go/base/intermediate/concurrency#goroutine">通道与完成协议</a> · <a href="/programming/go/base/intermediate/concurrency#race">共享状态与竞争</a> · <a href="/programming/go/base/intermediate/cancellation#cancel">取消信号与退出确认</a></p><p><a href="https://go.dev/ref/mod#go-sum-files" target="_blank" rel="noopener noreferrer">模块参考</a> · <a href="https://go.dev/doc/modules/layout" target="_blank" rel="noopener noreferrer">包与模块布局</a></p>`,26)])])}const k=a(t,[["render",o]]);export{h as __pageData,k as default};
